mapper.select:
select id, mix_area, glue, return_rate, remark, del_flag, create_by, create_time, update_by, update_time
  from t_fh_glue_return_rate
 where del_flag = '0'
 and mix_area = #{mixArea}
 and INSTR(glue, #{glue}) > 0
 and return_rate = #{returnRate}
 and del_flag = #{delFlag}

    order by create_time desc


    order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea} mix_Area, #{data.glue} glue
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_fh_glue_return_rate m inner join temp_table t on m.mix_Area = t.mix_Area and m.glue = t.glue and m.del_flag ='0'

mapper.insert:
insert into t_fh_glue_return_rate (id,mix_area,glue,return_rate,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{fhGlueReturnRate.mixArea,jdbcType= VARCHAR} mix_area, #{fhGlueReturnRate.glue,jdbcType= VARCHAR} glue, #{fhGlueReturnRate.returnRate,jdbcType=DOUBLE} return_rate, #{fhGlueReturnRate.remark,jdbcType= VARCHAR} remark, #{fhGlueReturnRate.delFlag,jdbcType= VARCHAR} del_flag, #{fhGlueReturnRate.createBy,jdbcType= VARCHAR} create_by, #{fhGlueReturnRate.createTime,jdbcType=TIMESTAMP} create_time, #{fhGlueReturnRate.updateBy,jdbcType= VARCHAR} update_by, #{fhGlueReturnRate.updateTime,jdbcType=TIMESTAMP} update_time
) x
